import base64, io, pathlib, subprocess, sys, tarfile
bundle=pathlib.Path('/content/q35moe-llama-hf-quality-harness')
bundle.mkdir(exist_ok=False)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode('')),mode='r:gz') as archive:
    archive.extractall(bundle, filter='data')
log=open('/content/q35moe-llama-hf-quality-worker.log','w')
process=subprocess.Popen([sys.executable,'-u',str(bundle/'worker.py')],stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
print({'pid':process.pid,'log':log.name})
